import { Component, For, Show } from "solid-js";

import { Layout } from "#core/ui/utilities/utilities-layout.js";
import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { Filigree } from "#core/ui-next/components/filigree.jsx";
import { Hotkeys } from "#core/ui-next/components/hotkeys.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { usePopupContext } from "#core/ui-next/components/popup.jsx";
import { AgeInfo, useAgeSelectModelContext } from "#core/ui-next/screens/create-game/age-select-model.js";
import { CreateGamePopupFrame } from "#core/ui-next/screens/create-game/create-game-popup-frame.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import style from "./age-select-popup.scss?url";

interface AgeTileProps extends AgeInfo {
	isSelected: boolean;
	onActivate: () => void;
}

const AgeSelectPopupTileComponent: Component<AgeTileProps> = (props) => {
	return (
		<Activatable
			class="img-unit-panelbox relative m-2 group flex-2"
			onActivate={props.onActivate}
		>
			<div
				class="absolute inset-x-0\.5 inset-y-1 bg-cover bg-right bg-no-repeat"
				style={{ "background-image": `url('blp:${props.bgImage}')` }}
			>
				<div class="age-select-popup-gradient absolute left-0 bottom-0" />
				<div class="absolute inset-0 flex flex-row">
					<div class="flex items-center w-1\/2 age-select-popup-content">
						<div
							class="flex items-center justify-center size-36 relative"
							style={{
								width: Layout.pixels(118),
								height: Layout.pixels(118),
								"background-image": "url(blp:hud_sub_circle_dis_128x128)",
								"background-repeat": "no-repeat",
								"background-size": "cover",
							}}
						>
							<Icon
								name={props.icon}
								class="size-22 -bottom-px relative"
							/>
						</div>
						<div class="flex flex-col items-center">
							<div class="font-title text-xl uppercase font-bold text-secondary">
								<L10n.Compose text={props.name} />
							</div>
							<Filigree.Small class="-mt-2" />
							<div class="text-accent-2 text-base">
								<L10n.Compose text={props.description} />
							</div>
						</div>
					</div>
				</div>
				<div class="img-rollover-highlight absolute inset-0 opacity-0 group-focus\:opacity-100 group-hover\:opacity-100 group-pressed\:opacity-100 pointer-events-none" />
				<Show when={props.isSelected}>
					<div class="absolute -left-2 top-4">
						<div
							class="flex flex-row items-start justify-start relative"
							style={{
								"border-image-source": `url('blp:tag_equipped.png')`,
								"border-image-slice": "1 6 1 1 fill",
								"border-image-repeat": "stretch",
								width: Layout.pixels(54),
								height: Layout.pixels(43),
							}}
						>
							<div
								class="img-icon-checkmark size-8 absolute mt-0\.5 ml-0\.5"
								style={{
									// eslint-disable-next-line solid/style-prop
									"fxs-background-image-tint": "black",
								}}
							/>
						</div>
					</div>
				</Show>
			</div>
		</Activatable>
	);
};

export const AgeSelectPopupTile = ComponentRegistry.register({
	name: "AgeSelectPopupTile",
	createInstance: AgeSelectPopupTileComponent,
	styles: [style],
});

const AgeSelectPopupComponent: Component = () => {
	const model = useAgeSelectModelContext();
	const popupContext = usePopupContext();

	function selectAge(age: AgeInfo) {
		model.setSelectedAge(age);
		popupContext.close("age-select");
	}

	function ageNameShort(age: AgeInfo) {
		// Example: "AGE_MODERN" -> "modern"
		const ageName = age.type.replace("AGE_", "").toLowerCase();
		return ageName;
	}

	return (
		<CreateGamePopupFrame onClose={() => popupContext.close("age-select")}>
			<Hotkeys
				hotkeys={[
					{ hotkeyAction: "accept", navTrayText: "LOC_GENERIC_SELECT" },
					{ hotkeyAction: "cancel", navTrayText: "LOC_GENERIC_BACK" },
				]}
			/>
			<div class="flex flex-col flex-auto m-4 items-center">
				<div class="text-2xl text-secondary mt-8 uppercase font-title">
					<L10n.Compose text="LOC_UI_CREATE_GAME_CHOOSE_A_STARTING_AGE" />
				</div>
				<Filigree.Small class="mb-4" />
				<div class="flex flex-col flex-auto w-full">
					<For each={model.sortedAges}>
						{(age) => (
							<AudioContextProvider
								segment="AgeSelectButton"
								vars={{ ageType: ageNameShort(age) }}
							>
								<AgeSelectPopupTile
									{...age}
									isSelected={age.type == model.selectedAge.type}
									onActivate={() => selectAge(age)}
								/>
							</AudioContextProvider>
						)}
					</For>
				</div>
			</div>
		</CreateGamePopupFrame>
	);
};

export const AgeSelectPopup = ComponentRegistry.register("AgeSelectPopup", AgeSelectPopupComponent);
